-- Load shared-nattrans-runtime.mech first.
specialize MechHorizontalLaws (0, 1, 0, 0, 1, 0) as Laws
  with (W_Ops_Source := Run_Source, W_Ops_Middle := Run_Middle, W_Ops_Target := Run_Target)

def Delta : Run_Second_NatTrans Nat Point End PairEnd Right Left :=
  ((fun (x : Nat) (n : Nat * Nat) => (n.2, 5)),
   (fun (0 x : Nat) (0 y : Nat) (f : Nat -> Nat) => categoryRefl))
def FirstIdentityAlpha : Run_First_NatTrans Nat Nat IndexedEnd End (Constant 0) (Constant 1) :=
  Run_First_vcomp Nat Nat IndexedEnd End (Constant 0) (Constant 0) (Constant 1)
    (Run_First_idNat Nat Nat IndexedEnd End (Constant 0)) Alpha
def SecondIdentityBeta : Run_Second_NatTrans Nat Point End PairEnd Left Right :=
  Run_Second_vcomp Nat Point End PairEnd Left Left Right
    (Run_Second_idNat Nat Point End PairEnd Left) Beta

def pairCode : (Nat * Nat) -> Nat := fun (n : Nat * Nat) => natAdd (natMul n.1 100) n.2

def certifiedHorizontal : (F : Run_Composite_Base_Functor Nat Point IndexedEnd PairEnd) ->
    (G : Run_Composite_Base_Functor Nat Point IndexedEnd PairEnd) ->
    (alpha : Run_Composite_NatTrans Nat Point IndexedEnd PairEnd F G) ->
    (beta : Run_Composite_NatTrans Nat Point IndexedEnd PairEnd F G) ->
    (0 proof : (x : Nat) -> Laws_NatTransEqAt Nat Point IndexedEnd PairEnd F G alpha beta x) -> Nat -> Nat :=
  fun (F : Run_Composite_Base_Functor Nat Point IndexedEnd PairEnd)
      (G : Run_Composite_Base_Functor Nat Point IndexedEnd PairEnd)
      (alpha : Run_Composite_NatTrans Nat Point IndexedEnd PairEnd F G)
      (beta : Run_Composite_NatTrans Nat Point IndexedEnd PairEnd F G)
      (0 proof : (x : Nat) -> Laws_NatTransEqAt Nat Point IndexedEnd PairEnd F G alpha beta x)
      (x : Nat) => pairCode (alpha.1 x (natAdd x 13, 7))

def idLeftLhs : Run_Composite_NatTrans Nat Point IndexedEnd PairEnd (Run_Compose_Base_compFunctor Nat Nat Point IndexedEnd End PairEnd (Constant 0) Left) (Run_Compose_Base_compFunctor Nat Nat Point IndexedEnd End PairEnd (Constant 0) Right) :=
  (Run_hcomp Nat Nat Point IndexedEnd End PairEnd (Constant 0) (Constant 0) Left Right (Run_First_idNat Nat Nat IndexedEnd End (Constant 0)) Beta)

def idLeftRhs : Run_Composite_NatTrans Nat Point IndexedEnd PairEnd (Run_Compose_Base_compFunctor Nat Nat Point IndexedEnd End PairEnd (Constant 0) Left) (Run_Compose_Base_compFunctor Nat Nat Point IndexedEnd End PairEnd (Constant 0) Right) :=
  (Run_Compose_whiskerRight Nat Nat Point IndexedEnd End PairEnd Left Right Beta (Constant 0))

def idLeftLaw : Laws_W_Composite_NatTransEq Nat Point IndexedEnd PairEnd (Run_Compose_Base_compFunctor Nat Nat Point IndexedEnd End PairEnd (Constant 0) Left) (Run_Compose_Base_compFunctor Nat Nat Point IndexedEnd End PairEnd (Constant 0) Right) idLeftLhs idLeftRhs :=
  (Laws_idHcomp Nat Nat Point IndexedEnd End PairEnd (Constant 0) Left Right Beta)

def idLeftLeftAt : Nat -> Nat :=
  certifiedHorizontal (Run_Compose_Base_compFunctor Nat Nat Point IndexedEnd End PairEnd (Constant 0) Left) (Run_Compose_Base_compFunctor Nat Nat Point IndexedEnd End PairEnd (Constant 0) Right) idLeftLhs idLeftRhs (fun (x : Nat) => idLeftLaw x)

def idLeftRightAt : Nat -> Nat :=
  certifiedHorizontal (Run_Compose_Base_compFunctor Nat Nat Point IndexedEnd End PairEnd (Constant 0) Left) (Run_Compose_Base_compFunctor Nat Nat Point IndexedEnd End PairEnd (Constant 0) Right) idLeftRhs idLeftLhs
